		return err
	}
	if _, err := r.Cookie(CookieName); err == nil && r.Header.Get("Authorization") == "" {
		http.SetCookie(w, a.sessionCookie("", -1))
	}
	w.WriteHeader(http.StatusNoContent)
	return nil
