	}
	if f.ResourceID != nil {
		add("resource_id = $%d", *f.ResourceID)
	}
	if f.OrgID != nil {
		add("org_id = $%d", *f.OrgID)
	}
	where := ""
	if len(conds) > 0 {
		where = " WHERE " + strings.Join(conds, " AND ")
	}
	var total int
	if err := t.q.QueryRow(ctx, "SELECT count(*) FROM iam.role_bindings"+where, args...).Scan(&total); err != nil {
